import {shouldContinueToolLoop, sumAggregateUsage} from './orchestratorHelpers.js';
import type {ToolRegistry} from './tools/registry.js';
import type {ToolCall, UsageMetadata} from '../types/ai.js';

// All three conditions matter; dropping the registry check spins the tool loop.

const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
const REGISTRY = {} as ToolRegistry;

describe('shouldContinueToolLoop', () => {
  it('continues when the model requested a tool and a registry can run it', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
  });

  it('stops when no registry is configured, whatever the model asked for', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
  });

  it('stops when the model named no tool', () => {
    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
  });

  it('stops when the model finished for a reason other than tool use', () => {
    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
  });
});

describe('sumAggregateUsage', () => {
  it('sums usage across multiple rounds with reported usage ([validated by](../../specs/hal-engine-config-hooks/spec.md#L31))', () => {
    const usage: UsageMetadata[] = [
      {inputTokens: 11, outputTokens: 2, totalTokens: 13},
      {inputTokens: 23, outputTokens: 3, totalTokens: 26},
      {inputTokens: 37, outputTokens: 5, totalTokens: 42},
    ];

    const result = sumAggregateUsage(usage);

    expect(result).toEqual({inputTokens: 71, outputTokens: 10, totalTokens: 81});
  });

  it('sums usage while skipping undefined rounds ([validated by](../../specs/hal-engine-config-hooks/spec.md#L32))', () => {
    const usage: Array<UsageMetadata | undefined> = [
      {inputTokens: 2, outputTokens: 1, totalTokens: 3},
      undefined,
      {inputTokens: 7, outputTokens: 4, totalTokens: 11},
    ];

    const result = sumAggregateUsage(usage);

    expect(result).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
  });

  it('returns undefined when no rounds have reported usage ([validated by](../../specs/hal-engine-config-hooks/spec.md#L33))', () => {
    const usage: Array<UsageMetadata | undefined> = [];

    const result = sumAggregateUsage(usage);

    expect(result).toBeUndefined();
  });

  it('returns undefined when all rounds have undefined usage ([validated by](../../specs/hal-engine-config-hooks/spec.md#L34))', () => {
    const usage: Array<UsageMetadata | undefined> = [undefined, undefined];

    const result = sumAggregateUsage(usage);

    expect(result).toBeUndefined();
  });
});

